package glitch

import data.glitch_lib

weak_algorithms := {"des", "3des", "rc2", "rc4", "idea", "seed", "md5", "sha1", "sha-1"}

weak_tls_versions := {"tlsv1.0", "tlsv1.1", "sslv3", "tls1.0", "tls1.1"}

weak_modes := {"ecb", "cbc"}

weak_key_indicators := {"fixed_salt", "hardcoded_iv", "static_key", "predictable_seed", "math_random", "pseudo_random"}

encryption_attrs := {"encryption_algorithm", "sse_algorithm", "algorithm", "cipher", "crypto_algorithm", "key_algorithm"}

key_size_attrs := {"key_size", "key_length", "bits", "key_bits", "rsa_bits", "dsa_bits"}

tls_version_attrs := {"tls_version", "ssl_policy", "min_tls_version", "minimum_tls_version", "ssl_protocol"}

mode_attrs := {"mode", "cipher_mode", "block_mode", "encryption_mode"}

is_weak_algorithm(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    weak_algorithms[_] == lower
} else {
    value.ir_type == "String"
    regex.match("(?i).*\\b(custom|proprietary|homegrown|internal|legacy|null|none|no.encryption|plaintext|unencrypted)\\b", value.value)
}

is_weak_tls_version(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    weak_tls_versions[_] == lower
}

is_weak_mode(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    weak_modes[_] == lower
}

has_weak_key_indicator(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    regex.match(sprintf("(?i).*%s.*", [weak_key_indicators[_]]), n.value)
}

is_small_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
} else {
    value.ir_type == "String"
    regex.match("^\\s*(10(2[0-3]|[0-2][0-9])|[0-9]{1,2})\\s*$", value.value)
}

find_encryption_attribute(attrs) = attr {
    attrs[_].name == encryption_attrs[_]
    attr := attrs[_]
}

find_key_size_attribute(attrs) = attr {
    attrs[_].name == key_size_attrs[_]
    attr := attrs[_]
}

find_tls_version_attribute(attrs) = attr {
    attrs[_].name == tls_version_attrs[_]
    attr := attrs[_]
}

find_mode_attribute(attrs) = attr {
    attrs[_].name == mode_attrs[_]
    attr := attrs[_]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name == encryption_attrs[_]
    is_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm. (CWE-326)"
    }
}

