package glitch

import data.glitch_lib

weak_algorithms := {"des", "3des", "rc2", "rc4", "idea", "seed", "md5", "sha1", "sha-1", "md5_crypt"}

weak_tls_versions := {"tlsv1.0", "tlsv1.1", "sslv3", "tls1.0", "tls1.1"}

weak_modes := {"ecb", "cbc"}

weak_key_indicators := {"fixed_salt", "hardcoded_iv", "static_key", "predictable_seed", "math_random", "pseudo_random"}

encryption_attrs := {"encryption_algorithm", "sse_algorithm", "algorithm", "cipher", "crypto_algorithm", "key_algorithm", "encrypt", "hash"}

key_size_attrs := {"key_size", "key_length", "bits", "key_bits", "rsa_bits", "dsa_bits", "salt_size"}

tls_version_attrs := {"tls_version", "ssl_policy", "min_tls_version", "minimum_tls_version", "ssl_protocol"}

mode_attrs := {"mode", "cipher_mode", "block_mode", "encryption_mode"}

cipher_suite_attrs := {"cipher_suites", "cipher_suite"}

check_weak_string(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    weak_algorithms[lower_val]
} else {
    value.ir_type == "String"
    regex.match("(?i).*\\b(custom|proprietary|homegrown|internal|legacy|null|none|no.encryption|plaintext|unencrypted)\\b", value.value)
}

check_weak_tls_version(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    weak_tls_versions[lower_val]
}

check_weak_mode_string(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    weak_modes[lower_val]
}

check_weak_mode_in_string(value) {
    value.ir_type == "String"
    regex.match("(?i)_(cbc|ecb)\\b", value.value)
}

has_weak_key_indicator(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    pattern := weak_key_indicators[_]
    regex.match(sprintf("(?i).*%s.*", [pattern]), n.value)
}

check_small_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
} else {
    value.ir_type == "String"
    regex.match("^\\s*(10(2[0-3]|[0-2][0-9])|[0-9]{1,2})\\s*$", value.value)
}

all_nested_values(node) = values {
    values = {n |
        walk(node, [_, n])
        n.ir_type != "BlockExpr"
    }
}

check_function_call_weak_algorithm(node) {
    node.ir_type == "FunctionCall"
    regex.match("(?i)(hash|encrypt|digest)", node.name)
    arg := node.args[_]
    check_weak_string(arg)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    block := {parent | true} | {ub | ub := parent.unit_blocks[_]}

    node := block[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name == encryption_attrs[_]
    check_weak_string(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm. (CWE-326)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    block := {parent | true} | {ub | ub := parent.unit_blocks[_]}

    node := block[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name == cipher_suite_attrs[_]

    vals := all_nested_values(attr.value)
    val := vals[_]
    val.ir_type == "String"
    regex.match("(?i)_(cbc|ecb|rc4|des|3des|md5|sha1)\\b", val.value)

    result := {
        "type": "sec_weak_crypt",
